DROP SCHEMA IF EXISTS 	Simoncelli_Capital;

CREATE SCHEMA Simoncelli_Capital;
USE Simoncelli_Capital;

CREATE TABLE customer_details(
customer_id INT,
full_name VARCHAR(250),
first_name VARCHAR(100),
last_name VARCHAR(200),
email VARCHAR(150),
investor_category VARCHAR (100),
location VARCHAR(250),
PRIMARY KEY(customer_id)
);


CREATE TABLE accounts_dim(
account_id INT,
customer_id INT, #foreign key from customer_details
main_account INT,
acct_open_status INT,
acct_open_date VARCHAR(200),
PRIMARY KEY(account_id)
);




CREATE TABLE holdings_dim(
account_id INT, #foreign key from accounts
ticker VARCHAR(8), #foreign key and a primary key
account_id_ticker VARCHAR(250),
value DOUBLE,
quantity BIGINT,
date DATE,
PRIMARY KEY (account_id_ticker)
);

#16,625,000 / 144.87 = ~114,756 shares
#20,995,000 / 744.00 = ~28,219 shares
#27,075,000 / 94.28 = ~287,185 shares
#8,455,000 / 97.82 = ~86,437 shares
#21,850,000 / 396.55 = ~55,089 shares


CREATE TABLE security_masterlist(
id BIGINT, 
security_name TEXT,
ticker VARCHAR(8),
sec_type VARCHAR(100),
major_asset_class VARCHAR(100),
minor_asset_class VARCHAR(100),
PRIMARY KEY(ticker)
);





#TABLE WITH PRICES - ONLY ADJUSTED CLOSE PRICES
CREATE TABLE pricing_daily_new(
date DATE  NOT NULL,
ticker VARCHAR(4) NOT NULL,
ticker_date VARCHAR(15) NOT NULL PRIMARY KEY,
price_type  VARCHAR(9) NOT NULL,
price NUMERIC(10,6) NOT NULL
);


#QUESTION 1 -  Return per security and for the whole portfolio
DROP PROCEDURE IF EXISTS q1_returns;
DELIMITER $$
CREATE PROCEDURE q1_returns(IN n_months INT)
BEGIN
DECLARE start_date DATE;
DECLARE end_date   DATE;
SELECT MAX(date) INTO end_date FROM pricing_daily_new;   # most recent day
SET start_date = DATE_SUB(end_date, INTERVAL n_months MONTH);

# Total return for each security over the window
SELECT DISTINCT y.ticker,  CONCAT(n_months, 'M') AS time_window, ROUND(y.end_price / y.start_price - 1, 4) AS period_return
FROM (SELECT ticker,
FIRST_VALUE(price) OVER (PARTITION BY ticker ORDER BY date) AS start_price,
FIRST_VALUE(price) OVER (PARTITION BY ticker ORDER BY date DESC) AS end_price
FROM pricing_daily_new
WHERE price_type = 'Adj Close'
AND date BETWEEN start_date AND end_date
AND ticker IN ('IXN', 'QQQ', 'IEF', 'VNQ', 'GLD')) y 
ORDER BY period_return DESC;

# Total return for the whole portfolio over the window (weighted sum)
SELECT 'CLIENT PORTFOLIO' AS portfolio, CONCAT(n_months, 'M') AS time_window,
ROUND(SUM(y.weight * (y.end_price / y.start_price - 1)), 4) AS period_return
FROM (SELECT DISTINCT ticker,
FIRST_VALUE(price) OVER (PARTITION BY ticker ORDER BY date) AS start_price,
FIRST_VALUE(price) OVER (PARTITION BY ticker ORDER BY date DESC) AS end_price,
CASE ticker
WHEN 'IXN' THEN 0.175 WHEN 'QQQ' THEN 0.221
WHEN 'IEF' THEN 0.285 WHEN 'VNQ' THEN 0.089
WHEN 'GLD' THEN 0.230 END AS weight
FROM pricing_daily_new
WHERE price_type = 'Adj Close'
AND date BETWEEN start_date AND end_date
AND ticker IN ('IXN', 'QQQ', 'IEF', 'VNQ', 'GLD')) y;
END$$
DELIMITER ;

CALL q1_returns(12);
CALL q1_returns(18);
CALL q1_returns(24);

#QUESTION 2 - CORRELATIONS
DROP PROCEDURE IF EXISTS q2_correlations;
DELIMITER $$
CREATE PROCEDURE q2_correlations(IN n_months INT)
BEGIN
DECLARE start_date DATE;
DECLARE end_date   DATE;
SELECT MAX(date) INTO end_date FROM pricing_daily_new;   # most recent day
SET start_date = DATE_SUB(end_date, INTERVAL n_months MONTH);

SELECT CONCAT(n_months, 'M') AS time_window,
a.ticker AS asset_1,
b.ticker AS asset_2,
ROUND((AVG(a.daily_ret * b.daily_ret) - AVG(a.daily_ret) * AVG(b.daily_ret)) / (STD(a.daily_ret) * STD(b.daily_ret)), 3) AS correlation
FROM (SELECT ticker, date,
(price / LAG(price, 1) OVER (PARTITION BY ticker ORDER BY date)) - 1 AS daily_ret
FROM pricing_daily_new
WHERE price_type = 'Adj Close'
AND date BETWEEN start_date AND end_date
AND ticker IN ('IXN', 'QQQ', 'IEF', 'VNQ', 'GLD')) a
JOIN (SELECT ticker, date,
(price / LAG(price, 1) OVER (PARTITION BY ticker ORDER BY date)) - 1 AS daily_ret
FROM pricing_daily_new
WHERE price_type = 'Adj Close'
AND date BETWEEN start_date AND end_date
AND ticker IN ('IXN', 'QQQ', 'IEF', 'VNQ', 'GLD')) b ON a.date = b.date
WHERE a.daily_ret IS NOT NULL
AND b.daily_ret IS NOT NULL
AND a.ticker < b.ticker
GROUP BY a.ticker, b.ticker
ORDER BY correlation DESC;
END$$
DELIMITER ;
CALL q2_correlations(6);
CALL q2_correlations(12);
CALL q2_correlations(18);
CALL q2_correlations(24);

#QUESTION 3 - SIGMA, VOLATILITY - last 6 and 12 months as required in the assignment
DROP PROCEDURE IF EXISTS q3_risk;
DELIMITER $$
CREATE PROCEDURE q3_risk(IN n_months INT)
BEGIN
DECLARE start_date DATE;
DECLARE end_date   DATE;
SELECT MAX(date) INTO end_date FROM pricing_daily_new;   # most recent day
SET start_date = DATE_SUB(end_date, INTERVAL n_months MONTH);

# Sigma for each security
SELECT CONCAT(n_months, 'M') AS time_window,
y.ticker,
ROUND(STD(y.daily_ret) * SQRT(250), 4) AS ann_vol
FROM (SELECT ticker, date,
(price / LAG(price, 1) OVER (PARTITION BY ticker ORDER BY date)) - 1 AS daily_ret
FROM pricing_daily_new
WHERE price_type = 'Adj Close'
AND date BETWEEN start_date AND end_date
AND ticker IN ('IXN', 'QQQ', 'IEF', 'VNQ', 'GLD')) y
WHERE y.daily_ret IS NOT NULL
GROUP BY y.ticker
ORDER BY ann_vol DESC;

# QUESTION 3 -Sigma for the whole portfolio (captures diversification)
SELECT CONCAT(n_months, 'M') AS time_window,
'CLIENT PORTFOLIO' AS portfolio,
ROUND(STD(port_ret) * SQRT(250), 4) AS ann_vol
FROM (SELECT date, SUM(CASE
WHEN ticker = 'IXN' THEN daily_ret * 0.175
WHEN ticker = 'QQQ' THEN daily_ret * 0.221
WHEN ticker = 'IEF' THEN daily_ret * 0.285
WHEN ticker = 'VNQ' THEN daily_ret * 0.089
WHEN ticker = 'GLD' THEN daily_ret * 0.230 END) AS port_ret
FROM (SELECT ticker, date,
(price / LAG(price, 1) OVER (PARTITION BY ticker ORDER BY date)) - 1 AS daily_ret
FROM pricing_daily_new
WHERE price_type = 'Adj Close'
AND date BETWEEN start_date AND end_date
AND ticker IN ('IXN', 'QQQ', 'IEF', 'VNQ', 'GLD')) d
WHERE daily_ret IS NOT NULL
GROUP BY date) port;
END$$
DELIMITER ;

CALL q3_risk(6);
CALL q3_risk(12);

# SHARPE RATIO - single 3-year window (36M)
# RF = 3.68% (annualised) 
# Risk-free rate: most recent value of the 3-month U.S. Treasury Bill (3.68%).
#   Board of Governors of the Federal Reserve System (US). (2026).
#   3-Month Treasury Bill Secondary Market Rate, Discount Basis [DTB3]
#   [Data set]. FRED, Federal Reserve Bank of St. Louis. Retrieved June 20,
#   2026, from https://fred.stlouisfed.org/series/DTB3

DROP PROCEDURE IF EXISTS q_sharpe;
DELIMITER $$
CREATE PROCEDURE q_sharpe(IN n_months INT)
BEGIN
DECLARE start_date DATE;
DECLARE end_date   DATE;
SELECT MAX(date) INTO end_date FROM pricing_daily_new;  
SET start_date = DATE_SUB(end_date, INTERVAL n_months MONTH);

# Sharpe for each
SELECT CONCAT(n_months, 'M') AS time_window,
y.ticker,
ROUND(AVG(y.daily_ret) * 250, 4) AS ann_return,
ROUND(STD(y.daily_ret) * SQRT(250), 4) AS ann_vol,
# 0.0368 = risk-free rate: most recent 3-month U.S. T-Bill (3.68%); source: FRED, series DTB3
ROUND((AVG(y.daily_ret) * 250 - 0.0368) / (STD(y.daily_ret) * SQRT(250)), 3) AS sharpe_ratio
FROM (SELECT ticker, date,
(price / LAG(price, 1) OVER (PARTITION BY ticker ORDER BY date)) - 1 AS daily_ret
FROM pricing_daily_new
WHERE price_type = 'Adj Close'
AND date BETWEEN start_date AND end_date
AND ticker IN ('IXN', 'QQQ', 'IEF', 'VNQ', 'GLD')) y
WHERE y.daily_ret IS NOT NULL
GROUP BY y.ticker
ORDER BY sharpe_ratio DESC;

# Sharpe CURRENT portfolio
SELECT CONCAT(n_months, 'M') AS time_window,
'CLIENT PORTFOLIO' AS portfolio,
ROUND(AVG(port_ret) * 250, 4) AS ann_return,
ROUND(STD(port_ret) * SQRT(250), 4) AS ann_vol,
ROUND((AVG(port_ret) * 250 - 0.0368) / (STD(port_ret) * SQRT(250)), 3) AS sharpe_ratio
FROM (SELECT date, SUM(CASE
WHEN ticker = 'IXN' THEN daily_ret * 0.175
WHEN ticker = 'QQQ' THEN daily_ret * 0.221
WHEN ticker = 'IEF' THEN daily_ret * 0.285
WHEN ticker = 'VNQ' THEN daily_ret * 0.089
WHEN ticker = 'GLD' THEN daily_ret * 0.230 END) AS port_ret
FROM (SELECT ticker, date,
(price / LAG(price, 1) OVER (PARTITION BY ticker ORDER BY date)) - 1 AS daily_ret
FROM pricing_daily_new
WHERE price_type = 'Adj Close'
AND date BETWEEN start_date AND end_date
AND ticker IN ('IXN', 'QQQ', 'IEF', 'VNQ', 'GLD')) d
WHERE daily_ret IS NOT NULL
GROUP BY date) port;
END$$
DELIMITER ;

CALL q_sharpe(36);

# QUESTION 4 AND 5 OPTIMIZED PROTFOLIO
DROP PROCEDURE IF EXISTS new_sharpe;
DELIMITER $$
CREATE PROCEDURE new_sharpe(IN n_months INT)
BEGIN
DECLARE start_date DATE;
DECLARE end_date DATE;
SELECT MAX(date) INTO end_date FROM pricing_daily_new; # most recent
SET start_date = DATE_SUB(end_date, INTERVAL n_months MONTH);
# Sharpe for each
SELECT CONCAT(n_months, 'M') AS time_window,
y.ticker,
ROUND(AVG(y.daily_ret) * 250, 4) AS ann_return,
ROUND(STD(y.daily_ret) * SQRT(250), 4) AS ann_vol,
# 0.0368 = risk-free rate: most recent 3-month U.S. T-Bill (3.68%); source: FRED, series DTB3
ROUND((AVG(y.daily_ret) * 250 - 0.0368) / (STD(y.daily_ret) * SQRT(250)), 3) AS sharpe_ratio
FROM (SELECT ticker, date,
(price / LAG(price, 1) OVER (PARTITION BY ticker ORDER BY date)) - 1 AS daily_ret
FROM pricing_daily_new
WHERE price_type = 'Adj Close'
AND date BETWEEN start_date AND end_date
AND ticker IN ('IXN', 'IEF', 'VNQ', 'GLD', 'AVDV', 'VTIP', 'DBC')) y
WHERE y.daily_ret IS NOT NULL
GROUP BY y.ticker
ORDER BY sharpe_ratio DESC;

# Sharpe del portafoglio (pesi cliente)
SELECT CONCAT(n_months, 'M') AS time_window,
'CLIENT PORTFOLIO' AS portfolio,
ROUND(AVG(port_ret) * 250, 4) AS ann_return,
ROUND(STD(port_ret) * SQRT(250), 4) AS ann_vol,
ROUND((AVG(port_ret) * 250 - 0.0368) / (STD(port_ret) * SQRT(250)), 3) AS sharpe_ratio
FROM (SELECT date, SUM(CASE
WHEN ticker = 'IXN' THEN daily_ret * 0.18
WHEN ticker = 'AVDV' THEN daily_ret * 0.22
WHEN ticker = 'IEF' THEN daily_ret * 0.06
WHEN ticker = 'VTIP' THEN daily_ret * 0.24
WHEN ticker = 'VNQ' THEN daily_ret * 0.05
WHEN ticker = 'DBC' THEN daily_ret * 0.07
WHEN ticker = 'GLD' THEN daily_ret * 0.18 END) AS port_ret
FROM (SELECT ticker, date,
(price / LAG(price, 1) OVER (PARTITION BY ticker ORDER BY date)) - 1 AS daily_ret
FROM pricing_daily_new
WHERE price_type = 'Adj Close'
AND date BETWEEN start_date AND end_date
AND ticker IN ('IXN', 'AVDV', 'IEF', 'VNQ', 'GLD', 'VTIP', 'DBC')) d
WHERE daily_ret IS NOT NULL
GROUP BY date) port;
END$$
DELIMITER ;
CALL new_sharpe(36);
